["type"] = "custom",
["custom"] = "function(allstates, event, triggerNum, triggerStates)\n    if event == \"TRIGGER\" and 1 == triggerNum then\n        allstates[\"\"] = allstates[\"\"] or {\n            progressType = \"timed\",\n            expirationTime = 0,\n            duration = 10,\n        }\n        \n        local state = allstates[\"\"]\n        local maxTime = state.expirationTime\n        local bars, last = {}\n        \n        for k, v in pairs(triggerStates) do\n            bars[k] = v\n            \n            if v.expirationTime >= maxTime then\n                last = k\n                maxTime = v.expirationTime\n            end\n        end\n        \n        if last then\n            for k, v in pairs(bars[last]) do\n                state[k] = v\n            end\n            \n            state.additionalProgress = {}\n            \n            local w = 4 / (aura_env.region.width / state.duration)\n            \n            --bars[last] = nil\n            \n            for k, v in pairs(bars) do\n                tinsert(state.additionalProgress, {\n                        direction = \"backward\",\n                        width = w,\n                        offset = (state.expirationTime - v.expirationTime)\n                })\n            end\n        end\n        \n        state.show = true\n        state.changed = true\n        \n        return true\n    end\nend",
