["customText"] = "--Code by Revvez\nfunction()\n    if aura_env.states[7].show then\n        aura_env.critchance = aura_env.states[7].criticalpercent\n        if aura_env.states[4].show then\n            aura_env.critchance = aura_env.critchance + aura_env.states[4].stacks * 15\n        end\n        if aura_env.states[5].show then\n            aura_env.critchance = aura_env.critchance + 20\n        end\n        if aura_env.states[6].show then\n            aura_env.critchance = aura_env.critchance + 25\n        end\n        if aura_env.critchance > 85 then \n            aura_env.region:SetGlow(true)\n        end\n        if aura_env.critchance <= 85 then\n            aura_env.region:SetGlow(false)\n        end\n        \n        return aura_env.critchance\n    end\n    \nend",
