["init"] = {
["custom"] = "--Default\nlocal texturePath = \"Interface\\\\Addons\\\\WeakAuras\\\\PowerAurasMedia\\\\Auras\\\\Aura45\"\n\n\nif aura_env.config.Crosshair == 1 then\n    --Chevron\n    texturePath = \"uitools-icon-chevron-down\"  \n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 2 then   \n    --Crosshair\n    texturePath = \"uitools-icon-plus\"    \n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 3 then   \n    --Diamond\n    texturePath = \"UF-SoulShard-FX-FrameGlow\"\n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 4 then   \n    --Flatline\n    texturePath = \"uitools-icon-minus\"\n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 5 then   \n    --If glowing Star\n    texturePath = \"AftLevelup-WhiteStarBurst\"\n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 6 then \n    texturePath = \"Interface\\\\Addons\\\\WeakAuras\\\\PowerAurasMedia\\\\Auras\\\\Aura72\"\n    aura_env.region:SetScale(.5)\n    \nelseif aura_env.config.Crosshair == 7 then   \n    --Ring\n    texturePath = \"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\circle_border5.tga\"\n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 8 then   \n    --Tech Arrow\n    texturePath = \"ProgLan-w-4\" \n    aura_env.region:SetScale(1)\n    \nelseif aura_env.config.Crosshair == 9 then   \n    --X\n    texturePath = \"uitools-icon-close\"    \n    aura_env.region:SetScale(1)\n    \nend\n\n--Elite\n--texturePath = \"Rare-Elite-Star\"\n\n--Solid Diamond\n--texturePath = \"UF-SoulShard-FX-HolderGlow\"\n\n\naura_env.region:SetTexture(texturePath)\n--aura_env.region:SetScale(.5)\n--aura_env.region:SetWidth(10)\n--aura_env.region:SetHeight(10)\n\n\n\n\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(event,button)\n    \n    if aura_env.config.HideOnRightClick then\n        if event == \"GLOBAL_MOUSE_UP\" then\n            if button == \"RightButton\" then\n                return true\n            end\n        end\n        \n    elseif aura_env.config.KeyOption > 1 then\n        \n        if aura_env.config.KeyOption == 2 and IsLeftAltKeyDown() then\n            return true \n        elseif aura_env.config.KeyOption == 4 and IsLeftControlKeyDown() then\n            return true\n        elseif aura_env.config.KeyOption == 3 and IsLeftShiftKeyDown() then\n            return true\n        end\n        \n    else\n        return true\n    end \n    \nend\n\n\n\n",
["spellIds"] = {
},
["custom_type"] = "event",
["names"] = {
},
["subeventPrefix"] = "SPELL",
["events"] = "GLOBAL_MOUSE_DOWN,GLOBAL_MOUSE_UP, MODIFIER_STATE_CHANGED,PLAYER_LOGIN,PLAYER_ENTERING_WORLD",
["custom_hide"] = "custom",
},
["untrigger"] = {
["custom"] = "function(event,button)\n    \n    if aura_env.config.HideOnRightClick then\n        if event == \"GLOBAL_MOUSE_DOWN\" then\n            if button == \"RightButton\" then\n                return true\n            end\n        end \n        \n    elseif aura_env.config.KeyOption > 1 then\n        \n        if aura_env.config.KeyOption == 2 and not IsLeftAltKeyDown() then\n            return true \n        elseif aura_env.config.KeyOption == 4 and not IsLeftControlKeyDown() then\n            return true\n        elseif aura_env.config.KeyOption == 3 and not IsLeftShiftKeyDown() then\n            return true\n        end\n        \n    else\n        return true\n    end \n    \nend\n\n\n\n",
},
},
["disjunctive"] = "any",
["customTriggerLogic"] = "function(trigger)\n    return trigger[2]\nend",
["activeTriggerMode"] = -10,
},
["internalVersion"] = 83,
["animation"] = {
["start"] = {
["colorR"] = 1,
["duration"] = "1000",
["alphaType"] = "custom",
["colorA"] = 1,
["colorG"] = 1,
["alphaFunc"] = "function(progress, start, delta)\n    \n    --[[if aura_env.config[\"HideOnRightClick\"] then\n        if IsMouseButtonDown(\"RightButton\") then\n            aura_env.region:Color(255,255,255,0)\n            return 0\n        else\n            aura_env.region:Color(255,255,255,255)\n            return 1\n        end\n    end\n]]--\n    \n    if aura_env.config[\"ShowOnKeyPress\"] then\n        \n        if aura_env.config[\"KeyOption\"] == 1 then\n            if IsLeftAltKeyDown() then\n                aura_env.region:Color(255,255,255,1)\n                return 1\n            else\n                aura_env.region:Color(255,255,255,0)\n                return 0\n            end\n        elseif  aura_env.config[\"KeyOption\"] == 2 then\n            if IsLeftShiftKeyDown() then\n                aura_env.region:Color(255,255,255,1)\n                return 1\n            else\n                aura_env.region:Color(255,255,255,0)\n                return 0\n            end\n        else\n            if IsLeftControlKeyDown() then\n                aura_env.region:Color(255,255,255,1)\n                return 1\n            else\n                aura_env.region:Color(255,255,255,0)\n                return 0\n            end\n        end\n        \n    end\n    \n    \nend\n\n\n",
