["ECUI"] = {
["outline"] = "OUTLINE",
["wagoID"] = "6nUSNpGW8",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
