},
},
["preferToUpdate"] = true,
["customText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["cooldownEdge"] = true,
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- Credit to Whispyr\n\n-- For auras with infinite duration\naura_env.maxTimestamp = 9999999\n\naura_env.evHandlers = {\n    [ \"OPTIONS\" ] = function( as ) return aura_env.InitAllStates( as, true ) end,\n    [ \"STATUS\" ] = function( as ) return aura_env.InitAllStates( as, true ) end,\n    --Main Aura - Update Current snapshots on target (Track state changes)\n    [ \"TRIGGER1\" ] = function( as, ts )\n        local changes\n        local targGUID = ts[ \"\" ] and ts[ \"\" ].GUID\n        for snapNum, snap in pairs( as[ \"\" ].snaps ) do\n            changes = aura_env.SetTrackChanges( as[ \"\" ], \"targCurSnap\"..snapNum, ( targGUID and snap.activeSnaps[ targGUID ] or false ), true ) or changes\n        end\n        return changes\n    end,\n    --CLEU Aura Apply / Refresh / Remove - Log GUID to snapshot tables if snapshot buffs present\n    [ \"TRIGGER4\" ] = function( as, ts )\n        if ts[ \"\" ] and ts[ \"\" ].eventTime then\n            for _, snap in pairs ( as[ \"\" ].snaps ) do \n                if ts[ \"\" ].isRemoval then \n                    snap.activeSnaps[ ts[ \"\" ].destGUID ] = nil\n                else --eventTime comparison may be unnecessary, buffExp existence may be sufficient, consider removing later\n                    snap.activeSnaps[ ts[ \"\" ].destGUID ] = ( snap.talent and ts[ \"\" ].eventTime <= snap.buffExp ) or nil\n                end\n            end\n        end\n    end,\n    --CLEU - GCD Spell Cast - Every buff that provides a snapshot allows for a number of GCDs. This trigger decrements the available for persistent buffs. (Track state changes)\n    [ \"TRIGGER5\" ] = function( as, ts )\n        if ts[ \"\" ] then \n            as[ \"\" ].nextGCD = ts[ \"\" ].expirationTime\n            --decrement GCDs for each persistent buff if GCD happened after buff applied, track highest values per snap\n            local snapBuffTalent\n            for _, snap in pairs( as[ \"\" ].snaps ) do\n                local highestSnapBuffVals = { GCDRemain = 0, buffExp = 0 }\n                if snap.talent and snap.buffExp > 0 then\n                    for _, snapBuff in pairs( snap.snapBuffs ) do\n                        if snapBuff.isPersist and snapBuff.GCDRemain > 0 and ts[ \"\" ].castTime > snapBuff.applyTime then\n                            snapBuff.GCDRemain = snapBuff.GCDRemain - 1\n                        end\n                        aura_env.UpdateSnapTrackTable( highestSnapBuffVals, snapBuff )\n                    end\n                    snapBuffTalent = true\n                end\n                if snapBuffTalent then\n                    return aura_env.UpdateSnapNextCastValues( as, highestSnapBuffVals, snap )\n                end\n            end\n        end\n    end,\n    --Snapshot 1 Buffs - Nightstalker \n    [ \"TRIGGER6\" ] = function( as, ts ) \n        return aura_env.EstablishSnapshotBuffs( as, ts, 1 ) --Nightstalker\n    end,\n    --Snapshot 1 Talent - Nightstalker (Track state changes)\n    [ \"TRIGGER7\" ] = function( as, ts ) \n        local snapNum = 1\n        as[ \"\" ].snaps[ snapNum ].talent = ( ts[ \"\" ] and ts[ \"\" ].stacks and ts[ \"\" ].stacks > 0 )\n        return aura_env.SetNextCastValues( as, as[ \"\" ].snaps[ snapNum ] )\n    end,\n}\n\n--Initialization--\naura_env.InitAllStates = function( as, forceReinit )\n    if not as[ \"\" ] or forceReinit then\n        as[ \"\" ] = { \n            show = true, \n            changed = true, \n            nextGCD = GetTime(),\n            snaps = {\n                [ 1 ] = aura_env.NewSnapTable( 1 ), --Nightstalker\n            },\n            --Condition values\n            targCurSnap1 = false,\n            nextCastSnap1 = false,\n            targCurSnap2 = false,\n            nextCastSnap2 = false,\n        }\n        return true\n    end\nend\n\naura_env.NewSnapTable = function( snapNum )\n    return {\n        buffExp = 0,\n        GCDRemain = 0,\n        activeSnaps = {},\n        talent = false,\n        snapBuffs = {},\n        snapNum = snapNum\n    }\nend\n\n-- Establish snapshot buffs, update Next Cast snapshots (Track state changes) --\naura_env.EstablishSnapshotBuffs = function( as, ts, snapNum )\n    local snap = as[ \"\" ].snaps[ snapNum ]\n    local buffsChanged\n    for buffKey, aura in pairs( ts ) do\n        if not snap.snapBuffs[ aura.auraInstanceID ] then --new snapshot buff\n            snap.snapBuffs[ aura.auraInstanceID ] = {\n                buffExp = ( aura.expirationTime == 0 and aura_env.maxTimestamp or aura.expirationTime ),\n                applyTime = aura.time,\n                isPersist = aura_env.snapPersistBuffValues[ buffKey ] and aura_env.snapPersistBuffValues[ buffKey ].isPersist,\n                GCDRemain = aura_env.snapPersistBuffValues[ buffKey ] and aura_env.snapPersistBuffValues[ buffKey ].maxGCDs or 1,\n                buffKey = buffKey\n            }\n            buffsChanged = true\n        end\n    end\n    --Remove missing auras, track highest values per snap\n    local highestSnapBuffVals = { GCDRemain = 0, buffExp = 0 }\n    for auraInstanceID, snapBuff in pairs( snap.snapBuffs ) do\n        if not ts[ snapBuff.buffKey ] then\n            snap.snapBuffs[ auraInstanceID ] = nil\n            buffsChanged = true\n        else\n            aura_env.UpdateSnapTrackTable( highestSnapBuffVals, snapBuff )\n        end\n    end\n    --Update Next Cast snapshot values if any changes\n    if buffsChanged then\n        return aura_env.UpdateSnapNextCastValues( as, highestSnapBuffVals, snap )\n    end\nend\n\naura_env.UpdateSnapTrackTable = function( trackTable, snapBuff )\n    for key, val in pairs( trackTable ) do\n        if snapBuff[ key ] > val then\n            trackTable[ key ] = snapBuff[ key ]\n        end\n    end\nend\n\naura_env.UpdateSnapNextCastValues = function( as, highestSnapBuffVals, snap )\n    for key, val in pairs( highestSnapBuffVals ) do snap[ key ] = val end\n    return aura_env.SetNextCastValues( as, snap )\nend\n\naura_env.SetNextCastValues = function( as, snap )\n    if snap.talent and snap.GCDRemain > 0 then\n        return aura_env.SetTrackChanges( as[ \"\" ], \"nextCastSnap\"..snap.snapNum, ( ( snap.buffExp - aura_env.config.resources.garrote.gcdLenience ) > as[ \"\" ].nextGCD ) or false, true )\n    else\n        return aura_env.SetTrackChanges( as[ \"\" ], \"nextCastSnap\"..snap.snapNum, false, true )\n    end\nend\n\n--Set the value, return true if the value has changed. Set changed in table if table is a state.\naura_env.SetTrackChanges = function( table, key, value, isState )\n    local oldVal = table[ key ]\n    if oldVal ~= value then --only if change\n        table[ key ] = value\n        if isState then table.changed = true end\n        return true\n    end\nend\n\n-- Lookup tables --\naura_env.snapPersistBuffValues = {\n    --No clean way to attribute GCDs that break stealth. \n    --The easiest way is to always assume Subterfuge / imp garrote gets only 2 GCDs (even though it's technically 3)\n    [ \"player 392401\" ] = { isPersist = true, maxGCDs = 2, },  --Imp Garrote\n    [ \"player 185422\" ] = { isPersist = true, maxGCDs = 6, },  --Dance\n}\n\n--Yes, a lookup table for Rogue GCD spell IDs\naura_env.rogueGCDs = { [ 5938 ] = \"\", [ 2094 ] = \"\", [ 31224 ] = \"\", [ 1776 ] = \"\", [ 385616 ] = \"\", [ 8676 ] = \"\",\n    [ 1833 ] = \"\", [ 185311 ] = \"\", [ 1725 ] = \"\", [ 1966 ] = \"\", [ 408 ] = \"\", [ 6770 ] = \"\", [ 315496 ] = \"\", [ 57934 ] = \"\",\n    [ 385408 ] = \"\", [ 360194 ] = \"\", [ 32645 ] = \"\", [ 51723 ] = \"\", [ 703 ] = \"\", [ 385627 ] = \"\", [ 1329 ] = \"\", [ 185565 ] = \"\",\n    [ 1943 ] = \"\", [ 121411 ] = \"\", [ 385424 ] = \"\", [ 200758 ] = \"\", [ 280719 ] = \"\", [ 277925 ] = \"\", [ 384631 ] = \"\",\n    [ 426591 ] = \"\", [ 319175 ] = \"\", [ 53 ] = \"\", [ 185438 ] = \"\", [ 197835 ] = \"\", [ 114014 ] = \"\", [ 271877 ] = \"\",\n    [ 51690 ] = \"\", [ 381989 ] = \"\", [ 196937 ] = \"\", [ 315341 ] = \"\", [ 13877 ] = \"\", [ 2098 ] = \"\", [ 195457 ] = \"\",\n    [ 185763 ] = \"\", [ 315508 ] = \"\", [ 430023 ] = \"\" }",
