["Soul Fragments (Havoc)"] = {
["iconSource"] = -1,
["wagoID"] = "r11CnDRVQ",
["parent"] = "Maintenance - LWA - Demon Hunter",
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
