["unevent"] = "timed",
["custom_type"] = "status",
["spellName"] = {
0,
},
["custom"] = "function(event, time, subEvent, _, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, ...)\n    local player = UnitGUID(\"player\")\n    -- Credit to Asakawa & Egraow\n    \n    -- Spell IDs\n    -- Consume:\n    -- 228532 - DA fragment\n    -- 178963 - Passive fragment\n    --\n    -- Shatter: (combat event fires when soul touches the ground)\n    -- 228537 - DA shatter\n    -- 209693 - Passive shatter\n    \n    \n    if event == \"SETUP\" then\n        aura_env.souls = {}\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        local encounterID = ...\n        \n        if encounterID then\n            aura_env.souls = {}\n        end\n        \n        return true\n    end\n    \n    if event == \"ST_EXPIRE\" and time then\n        aura_env.souls[time] = nil\n        \n        return true\n    end\n    \n    \n    -- Fragment Consumed\n    if player == destGUID then\n        if subEvent == \"SPELL_HEAL\" then\n            local spell = ...\n            \n            if spell == 228532 or spell == 178963 then\n                if aura_env.soulCount() > 0 then\n                    local lowTime, lowSoul = math.huge\n                    \n                    for startTime, timer in pairs(aura_env.souls) do \n                        if startTime < lowTime then\n                            lowTime = startTime\n                            lowSoul = timer\n                        end\n                    end\n                    \n                    lowSoul:Cancel()\n                    aura_env.souls[lowTime] = nil\n                end\n                \n                return true\n            end\n        end\n    end\n    \n    \n    -- Fragment Created\n    if player == sourceGUID then\n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            local spell = ...\n            \n            if spell == 209693 or spell == 228537 then\n                local startTime = GetTime()\n                \n                aura_env.souls[startTime] = C_Timer.NewTimer(30, function() WeakAuras.ScanEvents(\"ST_EXPIRE\", startTime) end)\n                \n                return true\n            end\n        end\n    end\n    \n    if aura_env.soulCount() == 0 and aura_env.config.maintenance.soul_havoc.behavior == 1 then\n        return false \n    end\n    \n    return true\nend",
["event"] = "Combat Log",
["customStacks"] = "function()\n    return aura_env.soulCount()\nend",
