["[林无双]自动嫁祸/误导 by 林无双"] = {
["outline"] = "OUTLINE",
["authorOptions"] = {
{
["type"] = "description",
["fontSize"] = "medium",
["text"] = "\n复制以下内容到宏中，使用宏即可自动嫁祸/误导\n\n/click LWS_AutoMisdirect LeftButton 1\n/click LWS_AutoMisdirect LeftButton 0",
["width"] = 2,
},
{
["useName"] = false,
["type"] = "header",
["text"] = "",
["width"] = 1,
},
{
["type"] = "input",
["useDesc"] = false,
["width"] = 2,
["default"] = "/click LWS_AutoMisdirect LeftButton 1  /click LWS_AutoMisdirect LeftButton 0",
["multiline"] = true,
["name"] = "自动 误导/嫁祸 宏",
["length"] = 10,
["key"] = "option",
["useLength"] = false,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://linwushuang.fun/",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["do_custom"] = true,
["custom"] = "-- by 林无双，参考：Chilly @ Draenor Abel.Wu HopeAsd TankMD\n\nlocal a = aura_env\nlocal spell = 57934\nlocal name = \"LWS_AutoMisdirect\"\nlocal btn = _G[name]\nlocal _, classEn = UnitClass(\"player\")\n\n\nfunction a:UpdateTank()\n    for unit in WA_IterateGroupMembers() do\n        if UnitGroupRolesAssigned(unit) == \"TANK\" then\n            self:UpdateButton(unit)\n            return\n        end\n    end\n    a:UpdateButton(\"pet\")\nend\n\nfunction a:UpdateButton(tank)\n    if not UnitExists(tank) then return end\n    if tank == \"pet\" and not UnitGUID(tank):find(\"Pet\") then return end\n    local spell = C_Spell.GetSpellInfo(spell)\n    \n    if not spell or not spell.name then print(aura_env.id, \"错误\", \"未知的技能 \" .. spell) end\n    \n    self.btn:SetAttribute(\"unit\", tank)\n    \n    if not self.btn.GUID or (self.btn.GUID and self.btn.GUID ~= UnitGUID(tank)) then\n        self.btn.GUID = UnitGUID(tank)\n        print(\"[林无双 自动目标] :\", \"目标 (\" ..\n            spell.name .. \")  -> \" .. GetUnitName(tank, true) .. \"(\" .. tank .. \")\")\n    end\nend\n\nfunction a:onInit()\n    if classEn == \"HUNTER\" then\n        spell = 34477\n    elseif classEn == \"ROGUE\" then\n        spell = 57934\n    end\n    \n    if not btn then\n        local region = WeakAuras.GetRegion(aura_env.id)\n        btn = CreateFrame(\"Button\", name, region, \"SecureActionButtonTemplate\")\n        \n        btn:SetAttribute(\"type\", \"spell\")\n        btn:SetAttribute(\"spell\", spell)\n        btn:SetAttribute(\"checkselfcast\", false)\n        btn:SetAttribute(\"checkfocuscast\", false)\n        btn:SetAttribute(\"allowVehicleTarget\", false)\n        \n        btn:SetAttribute(\"pressAndHoldAction\", \"1\")\n        btn:SetAttribute(\"typerelease\", \"spell\")\n        \n        btn:RegisterForClicks(\"LeftButtonDown\", \"LeftButtonUp\")\n    end\n    if not btn.lastSpell or (btn.lastSpell and btn.lastSpell ~= spell) then\n        local spell = C_Spell.GetSpellInfo(spell)\n        if not spell or not spell.name then print(aura_env.id, \"错误\", \"未知的技能 \" .. spell) end\n        print(\"[林无双 自动目标] :\", \"加载技能 (\" .. spell.name .. \")\")\n        btn.lastSpell = spell\n    end\n    \n    a.btn = btn\nend\n\na:onInit()\na:UpdateTank()",
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["spellIds"] = {
},
["custom"] = "function(e)\n    if e == \"GROUP_ROSTER_UPDATE\" then\n        if InCombatLockdown() then\n            aura_env.needUpdate = true\n        else\n            aura_env:UpdateTank()\n        end\n    elseif not InCombatLockdown() then -- 非战斗下才尝试更新\n        --立即更新\n        if aura_env.needUpdate then\n            aura_env:UpdateTank()\n            aura_env.needUpdate = false\n        else\n            --10秒检测一次，应对随机本BUG\n            if not aura_env.last or aura_env.last < GetTime() - 10 then\n                aura_env.last = GetTime()\n                aura_env:UpdateTank()\n                aura_env.needUpdate = false\n            end\n        end    \n    end\nend",
