k:New{questId={80873}, itemId=227432, waypoint={map=2339, x=0.5983, y=0.5643}, kp=10, spell=459917, itemRequirements={{id=210814, quantity=400}} }) -- Lyrendal, 400\n    :AddEntry(MKPT_UniqueBook:New{questId={83061}, itemId=224648, waypoint={map=2339, x=0.3983, y=0.2420}, kp=10, spell=453447, renown={majorFactionId=2590, levelRequired=12}}) -- Jewel-Etched Tailoring Notes\n    :AddEntry(MKPT_UniqueBook:New{questId={82634}, itemId=224036, waypoint={map=2213, x=0.5063, y=0.1680}, kp=10, spell=450840, currency={id=3056, quantity=565}}) -- And That's A Web-Wrap!\n    :AddEntry(MKPT_Treatise:New {questId={83735}, itemId=222547, waypoint={map=2339, x=0.5804, y=0.5645}, kp=1, spell=457719, atlasIcon=\"Professions-Crafting-Orders-Icon\", text=\"Inscription work order\"}) -- Algari Treatise on Tailoring (Requires skill 25)\n    :AddEntry(MKPT_WeeklyQuestItem:New {questId={84132}, itemId=228779, waypoint={map=2339, x=0.5971, y=0.5627}, kp=2, text=\"Quest: Tailoring Services Requested\"}) -- Algari Tailor's Notebook\n    :AddEntry(MKPT_WeeklyTreasure:New{questId={83269}, itemId=225221, kp=1}) -- \"Spool of Webweave\"\n    :AddEntry(MKPT_WeeklyTreasure:New{questId={83270}, itemId=225220, kp=1}) -- \"Machine Speaker's\" \n    :AddEntry(MKPT_DarkmoonQuest:New {questId={29520}, waypoint={map=407, x=0.5555, y=0.5500}, itemRequirements={{id=2320, quantity=1}, {id=2604, quantity=1}, {id=6260, quantity=1}}, kp=3}) -- Banners, Banners Everywhere!\n    :AddEntry(MKPT_CatchUp:New{questId={}, itemId=228738, atlasIcon=\"Professions-Crafting-Orders-Icon\", unlockRequirements={questIdIdx[83269], questIdIdx[83270], questIdIdx[84132]}, kp=1, text=PROFESSIONS_CRAFTING_ORDERS_PAGE_NAME:format(PROFESSIONS_CRAFTER_ORDER_TAB_NPC)}) -- Catch up mechanic\n}\n\naura_env.GetProfessions = function (refresh)\n    if aura_env.professions and not refresh then\n        return aura_env.professions\n    end\n    local professions = {}\n    for _, profession in pairs(db) do\n        if profession:IsLearned() then\n            professions[profession.id] = profession\n        end\n    end\n    \n    aura_env.professions = professions\n    \n    return professions\nend",
