["value"] = "function()\n    if aura_env.state and aura_env.state.finalStacks then\n        return true\n    end\nend",
},
["changes"] = {
{
["value"] = {
["custom"] = "local voiceID\nlocal hasAddOn = C_AddOns.IsAddOnLoaded(\"SharedMedia_Causese\")\nif hasAddOn then\n    for _, voice in pairs(C_VoiceChat.GetTtsVoices()) do\n        if string.match(voice.name, \"Zira\") then\n            voiceID = voice.voiceID\n            break\n        end\n    end\n    if voiceID then\n        local suffix = (aura_env.state.finalStacks > 1 and \" stacks\") or \" stack\"\n        C_VoiceChat.SpeakText(voiceID, aura_env.state.finalStacks..suffix, 1, 0.5, GetCVar(\"Sound_MasterVolume\")*100)\n    end\nend",
},
