["custom"] = "function(allstates, event, triggerNum, state)\n    allstates[\"\"] = allstates[\"\"] or {\n        show = true,\n        changed = true,\n        progressType = \"static\",\n        value = 0,\n        realValue = 0,\n        total = 100,\n        realTotal = UnitHealthMax(\"player\") / 2,\n    }\n    \n    local s = allstates[\"\"]\n    \n    if event == \"TRIGGER\" and triggerNum == 2 then \n        s.realValue = 0\n    elseif event == \"TRIGGER\" and state[\"\"] and state[\"\"].tooltip1 then\n        s.realValue = state[\"\"].tooltip1 or 0\n    elseif event == \"UNIT_MAXHEALTH\" then\n        s.realTotal = UnitHealthMax(\"player\") / 2\n    end\n    \n    \n    s.value = (s.realValue / s.realTotal) * 100\n    s.changed = true\n    \n    return true\nend",
